-- VenStore: timber renderer.
-- Grain comes from textures\plank.tga (generated by tools\WoodGen.cs: growth rings, knots, fibres,
-- pores). Every surface samples its own slice of it (offset, mirrored, rotated for posts) and is
-- tinted per wood type. Lighting is layered on in code: light from above, varnish sheen, chamfered
-- bevels, rounded posts, butt joints with nails and ambient-occlusion shadows where surfaces meet.
-- Zone themes (Theme.lua) can swap any surface for one of Blizzard's own city textures instead
-- (see MATERIALS below).
local _, addon = ...

local Wood = {}
addon.Wood = Wood

local WHITE = "Interface\\Buttons\\WHITE8X8"
local DISC = "Interface\\CharacterFrame\\TempPortraitAlphaMask" -- white disc when used as a plain texture
local PLANK = "Interface\\AddOns\\VenStore\\textures\\plank"
local PLANK_W, PLANK_H = 1024, 128
local PLANK_AVG = { 0.653, 0.389, 0.210 } -- average colour of plank.tga (printed by WoodGen)
local TEXELS_PER_PIXEL = 1.5              -- grain scale on screen
Wood.DISC = DISC
Wood.PLANK = PLANK

-- Surface colours come from the theme (Theme.lua), by role: "wall", "post", "shelf", "counter"...

local function Clamp(v)
    if v < 0 then return 0 elseif v > 1 then return 1 end
    return v
end

local function Shade(r, g, b, m)
    return Clamp(r * m), Clamp(g * m), Clamp(b * m)
end
Wood.Shade = Shade

-- ============================================================================
-- THEME HOOKS
-- ============================================================================
-- Wood.Tint(role, tone, fn): fn(r, g, b, theme) runs now with the role's colour times `tone`
-- (a number, or { r, g, b } multipliers), and again on every theme change. Every colour that
-- depends on the theme goes through here, so the shop repaints in place without rebuilding.
local hooks = {}

local function RunHook(h, theme)
    local c = addon.Theme.Colour(theme, h.role)
    local t = h.tone or 1
    local tr, tg, tb
    if type(t) == "table" then tr, tg, tb = t[1], t[2], t[3] else tr, tg, tb = t, t, t end
    h.fn(Clamp(c[1] * tr), Clamp(c[2] * tg), Clamp(c[3] * tb), theme)
end

function Wood.Tint(role, tone, fn)
    local h = { role = role, tone = tone, fn = fn }
    hooks[#hooks + 1] = h
    RunHook(h, addon.Theme.current)
    return h
end

function Wood.ApplyTheme(theme)
    for i = 1, #hooks do RunHook(hooks[i], theme) end
end

-- Current colour of a role (for one-off reads; anything that must follow the theme uses Tint).
function Wood.RoleColour(role, tone)
    local c = addon.Theme.Colour(addon.Theme.current, role)
    tone = tone or 1
    return Clamp(c[1] * tone), Clamp(c[2] * tone), Clamp(c[3] * tone)
end

-- Deterministic PRNG so every surface keeps the same grain between sessions.
local function NewRNG(seed)
    local s = (math.floor(seed or 1) * 7919 + 104729) % 233280
    return function(lo, hi)
        s = (s * 9301 + 49297) % 233280
        local f = s / 233280
        if lo then return lo + f * (hi - lo) end
        return f
    end
end
Wood.NewRNG = NewRNG

-- orientation "VERTICAL": first colour = bottom, second = top.
-- orientation "HORIZONTAL": first colour = left, second = right.
function Wood.GradientFile(tex, file, orientation, r1, g1, b1, a1, r2, g2, b2, a2)
    tex:SetTexture(file)
    tex:SetGradient(orientation, CreateColor(r1, g1, b1, a1), CreateColor(r2, g2, b2, a2))
end

function Wood.Gradient(tex, orientation, r1, g1, b1, a1, r2, g2, b2, a2)
    Wood.GradientFile(tex, WHITE, orientation, r1, g1, b1, a1, r2, g2, b2, a2)
end
local Gradient = Wood.Gradient

function Wood.Solid(parent, layer, sub, r, g, b, a)
    local t = parent:CreateTexture(nil, layer, nil, sub)
    t:SetColorTexture(r, g, b, a or 1)
    return t
end

-- Soft elliptical blob (shadows, knots, light pools, coins...).
function Wood.Disc(parent, layer, sub, r, g, b, a)
    local t = parent:CreateTexture(nil, layer, nil, sub)
    t:SetTexture(DISC)
    t:SetVertexColor(r, g, b, a or 1)
    return t
end

-- Soft shadow strip that fades away from an edge. side = "TOP"|"BOTTOM"|"LEFT"|"RIGHT"
-- (the edge of `anchor` where the shadow is darkest).
function Wood.EdgeShade(parent, anchor, side, size, alpha, layer, sub, r, g, b)
    r, g, b = r or 0, g or 0, b or 0
    local t = parent:CreateTexture(nil, layer or "ARTWORK", nil, sub or 0)
    if side == "TOP" then
        t:SetPoint("TOPLEFT", anchor, "TOPLEFT"); t:SetPoint("TOPRIGHT", anchor, "TOPRIGHT"); t:SetHeight(size)
        Gradient(t, "VERTICAL", r, g, b, 0, r, g, b, alpha)
    elseif side == "BOTTOM" then
        t:SetPoint("BOTTOMLEFT", anchor, "BOTTOMLEFT"); t:SetPoint("BOTTOMRIGHT", anchor, "BOTTOMRIGHT"); t:SetHeight(size)
        Gradient(t, "VERTICAL", r, g, b, alpha, r, g, b, 0)
    elseif side == "LEFT" then
        t:SetPoint("TOPLEFT", anchor, "TOPLEFT"); t:SetPoint("BOTTOMLEFT", anchor, "BOTTOMLEFT"); t:SetWidth(size)
        Gradient(t, "HORIZONTAL", r, g, b, alpha, r, g, b, 0)
    else
        t:SetPoint("TOPRIGHT", anchor, "TOPRIGHT"); t:SetPoint("BOTTOMRIGHT", anchor, "BOTTOMRIGHT"); t:SetWidth(size)
        Gradient(t, "HORIZONTAL", r, g, b, 0, r, g, b, alpha)
    end
    return t
end

-- Narrows the far (top) edge of a texture to fake a receding surface seen from above.
function Wood.Perspective(tex, inset)
    if tex.SetVertexOffset then
        tex:SetVertexOffset(UPPER_LEFT_VERTEX or 1, inset, 0)
        tex:SetVertexOffset(UPPER_RIGHT_VERTEX or 3, -inset, 0)
    end
end

-- ============================================================================
-- GRAIN TEXTURE
-- ============================================================================
-- Tints the plank texture so it averages (r, g, b).
local function TintGrain(tex, r, g, b)
    tex:SetVertexColor(Clamp(r / PLANK_AVG[1]), Clamp(g / PLANK_AVG[2]), Clamp(b / PLANK_AVG[3]))
end

-- Returns a function(width, height) that maps `tex` (showing the plank texture) to its own slice
-- of the grain, at a constant on-screen scale whatever size the surface is.
local function GrainMap(tex, seed, vertical)
    local rand = NewRNG(seed)
    local u0, vPick, mirrored = rand(), rand(), rand() < 0.5
    local function Map(w, h)
        if not w or not h or w <= 0 or h <= 0 then return end
        local along, across = vertical and h or w, vertical and w or h
        local uSpan = along * TEXELS_PER_PIXEL / PLANK_W
        local vSpan = math.min(1, across * TEXELS_PER_PIXEL / PLANK_H)
        local v0 = vPick * (1 - vSpan)
        local v1 = v0 + vSpan
        local ua, ub = u0, u0 + uSpan
        if mirrored then ua, ub = ub, ua end
        if vertical then
            -- rotate 90 degrees: texture u runs down the screen, v runs across it
            tex:SetTexCoord(ua, v0, ub, v0, ua, v1, ub, v1)
        else
            tex:SetTexCoord(ua, ub, v0, v1)
        end
    end
    return Map
end

-- ============================================================================
-- MATERIALS: Blizzard's own world textures, by file ID (see Theme.lua)
-- ============================================================================
-- A theme can give a role a material instead of plank grain:
--   { file = id, size = px }               tile the whole texture, `size` px per repeat
--   { file = id, band = { a0, a1 }, axis = "u" | "v" }
--       one strip of an atlas texture, stretched across the surface and repeated along it.
--       axis "u": a horizontal strip (rows a0..a1); "v": a vertical strip (columns a0..a1).
--       Strips are turned 90 degrees to fit surfaces that run the other way.
--   tint = { r, g, b }   multiplies the texture (default white)
--   boost = 0..1         adds a brightening copy: world textures are made to be lit in 3D and
--                        look dark when drawn flat on the UI
--   sheen = number       varnish highlight strength (default 0: stone and metal don't get one)

-- Does this client have the texture? (A missing file ID makes SetTexture return false.)
local loadable = {}
function Wood.CanLoad(file)
    if loadable[file] == nil then
        local probe = UIParent:CreateTexture(nil, "BACKGROUND")
        local ok = probe:SetTexture(file)
        loadable[file] = ok ~= false
        probe:SetTexture(nil)
        probe:Hide()
    end
    return loadable[file]
end

-- Texture coordinates for material `mat` on a w x h surface. `vertical` = the surface runs up
-- and down (posts). o1 / o2 shift where the repeat starts, so neighbouring surfaces differ.
local function MapMaterial(tex, mat, w, h, vertical, o1, o2)
    if not mat.band then
        local s = mat.size or 256
        tex:SetTexCoord(o1, o1 + w / s, o2, o2 + h / s)
        return
    end
    local a0, a1 = mat.band[1], mat.band[2]
    local along, across = vertical and h or w, vertical and w or h
    local scale = across / (a1 - a0)       -- screen px per texture unit
    local s0, s1 = o1, o1 + along / scale  -- span along the strip (repeats)
    local stripRunsU = (mat.axis or "u") == "u"
    if stripRunsU and not vertical then
        tex:SetTexCoord(s0, s1, a0, a1)
    elseif not stripRunsU and vertical then
        tex:SetTexCoord(a0, a1, s0, s1)
    elseif stripRunsU then
        -- horizontal strip on an upright surface: texture u runs down the screen, v across it
        tex:SetTexCoord(s0, a0, s1, a0, s0, a1, s1, a1)
    else
        -- vertical strip on a lying surface: texture v runs across the screen, u down it
        tex:SetTexCoord(a0, s0, a1, s0, a0, s1, a1, s1)
    end
end

-- A texture that shows either plank grain (in the role's colour) or the theme's material for the
-- role, and follows theme changes. Returns the skin: skin.Map(w, h) re-maps it to a new size;
-- skin.mat is the material in use (nil = wood). woodOnly ignores materials.
local function Skin(tex, role, seed, vertical, tone, mask, woodOnly)
    local grainMap = GrainMap(tex, seed, vertical)
    local rand = NewRNG((seed or 1) + 7777)
    local o1, o2 = rand(), rand()
    local skin = {}
    local boost

    function skin.Map(w, h)
        if w and h and w > 0 and h > 0 then skin.w, skin.h = w, h end
        if not skin.w then return end
        if skin.mat then
            MapMaterial(tex, skin.mat, skin.w, skin.h, vertical, o1, o2)
            if boost then MapMaterial(boost, skin.mat, skin.w, skin.h, vertical, o1, o2) end
        else
            grainMap(skin.w, skin.h)
        end
    end

    Wood.Tint(role, tone, function(r, g, b, theme)
        local mat = not woodOnly and theme and theme.materials and theme.materials[role] or nil
        if mat and not Wood.CanLoad(mat.file) then mat = nil end
        skin.mat = mat
        if mat then
            tex:SetTexture(mat.file, "REPEAT", "REPEAT")
            -- A tone below 1 (the dark cubby recess, the floor deck) darkens the material too.
            local k = type(tone) == "number" and math.min(tone, 1) or 1
            local t = mat.tint
            local mr, mg, mb = (t and t[1] or 1) * k, (t and t[2] or 1) * k, (t and t[3] or 1) * k
            tex:SetVertexColor(mr, mg, mb)
            if mat.boost and mat.boost > 0 then
                if not boost then
                    local layer, sub = tex:GetDrawLayer()
                    boost = tex:GetParent():CreateTexture(nil, layer, nil, sub)
                    boost:SetAllPoints(tex)
                    boost:SetBlendMode("ADD")
                    if mask then boost:AddMaskTexture(mask) end
                end
                boost:SetTexture(mat.file, "REPEAT", "REPEAT")
                boost:SetVertexColor(mr, mg, mb, mat.boost)
                boost:Show()
            elseif boost then
                boost:Hide()
            end
        else
            tex:SetTexture(PLANK, "REPEAT", "REPEAT")
            TintGrain(tex, r, g, b)
            if boost then boost:Hide() end
        end
        skin.Map()
    end)
    return skin
end
Wood.Skin = Skin

-- Grain (or the theme's material) on a bare texture, for `role` times `tone`. `mask` is applied to
-- any extra layers too. Returns the re-map function(width, height).
function Wood.ApplyGrain(tex, role, seed, vertical, tone, mask)
    return Skin(tex, role, seed, vertical, tone, mask).Map
end

-- ============================================================================
-- Wood.Paint(frame, role, seed, opts) - a board in the colour of `role` (see Theme.lua)
--   opts.tone    multiplier on the role colour: a number or { r, g, b }
--   opts.woodOnly   always plank grain, even when the theme gives the role a material
--   opts.grain   "H" (default) or "V" - direction the grain runs
--   opts.bevel   chamfered edge highlights/shadows (default true)
--   opts.round   cylindrical shading across the short axis (posts, rails)
--   opts.sheen   varnish highlight band (default true for horizontal grain)
--   opts.ends    darken the two ends of a horizontal board
--   opts.flip    light the bottom edge instead of the top (tops of shelves / floors)
--   opts.light   highlight strength at the lit edge (default 1.14)
--   opts.dark    brightness at the shaded edge (default 0.78)
-- ============================================================================
function Wood.Paint(frame, role, seed, opts)
    opts = opts or {}
    local vertical = opts.grain == "V"

    -- 0. Flat colour underneath (what you would see if the texture failed to load).
    local under = frame:CreateTexture(nil, "BACKGROUND", nil, 0)
    under:SetAllPoints()

    -- 1. Grain (or the theme's material).
    local grain = frame:CreateTexture(nil, "BACKGROUND", nil, 1)
    grain:SetAllPoints()
    local skin = Skin(grain, role, seed, vertical, opts.tone, nil, opts.woodOnly)
    frame:HookScript("OnSizeChanged", function(self, w, h) skin.Map(w, h) end)
    skin.Map(frame:GetWidth(), frame:GetHeight())

    -- 2. Light from above (or from the left on posts): a shade toward the far edge plus a warm lift
    --    on the lit edge.
    local shadeA = Clamp((1 - (opts.dark or 0.78)) * 1.6)
    local liftA = Clamp(((opts.light or 1.14) - 1) * 0.9)
    local shade = frame:CreateTexture(nil, "BACKGROUND", nil, 2)
    shade:SetAllPoints()
    local lift = frame:CreateTexture(nil, "BACKGROUND", nil, 2)
    lift:SetAllPoints()
    lift:SetBlendMode("ADD")
    if vertical then
        Gradient(shade, "HORIZONTAL", 0, 0, 0, 0, 0, 0, 0, shadeA)
        Gradient(lift, "HORIZONTAL", 1, 0.8, 0.55, liftA, 1, 0.8, 0.55, 0)
    elseif opts.flip then
        Gradient(shade, "VERTICAL", 0, 0, 0, 0, 0, 0, 0, shadeA)
        Gradient(lift, "VERTICAL", 1, 0.8, 0.55, liftA, 1, 0.8, 0.55, 0)
    else
        Gradient(shade, "VERTICAL", 0, 0, 0, shadeA, 0, 0, 0, 0)
        Gradient(lift, "VERTICAL", 1, 0.8, 0.55, 0, 1, 0.8, 0.55, liftA)
    end

    -- 3. Varnish sheen: a soft specular band in the upper third of the board. Its strength is the
    --    theme's varnish.
    local sheen
    if opts.sheen ~= false and not vertical then
        sheen = frame:CreateTexture(nil, "BACKGROUND", nil, 6)
        sheen:SetPoint("TOPLEFT", frame, "TOPLEFT", 0, -2)
        sheen:SetPoint("TOPRIGHT", frame, "TOPRIGHT", 0, -2)
        sheen:SetHeight(math.max(3, (frame:GetHeight() or 12) * 0.35))
        sheen:SetBlendMode("ADD")
    end

    -- 4. Cylindrical shading for posts / rails.
    if opts.round then
        if vertical then
            Wood.EdgeShade(frame, frame, "LEFT", 4, 0.30, "BACKGROUND", 7)
            Wood.EdgeShade(frame, frame, "RIGHT", 6, 0.55, "BACKGROUND", 7)
        else
            Wood.EdgeShade(frame, frame, "BOTTOM", 5, 0.50, "BACKGROUND", 7)
        end
    end

    -- 5. Darkened board ends (end grain absorbs more finish).
    if opts.ends then
        Wood.EdgeShade(frame, frame, "LEFT", 10, 0.40, "BACKGROUND", 7)
        Wood.EdgeShade(frame, frame, "RIGHT", 10, 0.40, "BACKGROUND", 7)
    end

    -- 6. Chamfered edges: bright top lip, dark underside.
    local hi, hi2, lo
    if opts.bevel ~= false then
        hi = frame:CreateTexture(nil, "ARTWORK", nil, 1)
        lo = frame:CreateTexture(nil, "ARTWORK", nil, 1)
        if vertical then
            hi:SetPoint("TOPLEFT"); hi:SetPoint("BOTTOMLEFT"); hi:SetWidth(1)
            lo:SetPoint("TOPRIGHT"); lo:SetPoint("BOTTOMRIGHT"); lo:SetWidth(2)
        else
            hi:SetPoint("TOPLEFT"); hi:SetPoint("TOPRIGHT"); hi:SetHeight(1)
            hi2 = frame:CreateTexture(nil, "ARTWORK", nil, 1)
            hi2:SetPoint("TOPLEFT", hi, "BOTTOMLEFT"); hi2:SetPoint("TOPRIGHT", hi, "BOTTOMRIGHT"); hi2:SetHeight(3)
            lo:SetPoint("BOTTOMLEFT"); lo:SetPoint("BOTTOMRIGHT"); lo:SetHeight(2)
        end
    end

    -- Everything that depends on the colour, re-run on each theme change.
    -- (The skin above re-textures the grain layer itself; it was registered first, so skin.mat is
    -- already current here.)
    return Wood.Tint(role, opts.tone, function(r, g, b, theme)
        under:SetColorTexture(r, g, b, 1)
        if sheen then
            local a = 0.07 * (skin.mat and (skin.mat.sheen or 0) or (theme and theme.varnish or 1))
            Gradient(sheen, "VERTICAL", 1, 0.9, 0.7, 0, 1, 0.9, 0.7, a)
        end
        if hi then
            local hr, hg, hb = Shade(r, g, b, 1.75)
            local sr, sg, sb = Shade(r, g, b, 0.28)
            hi:SetColorTexture(hr, hg, hb, vertical and 0.45 or 0.55)
            lo:SetColorTexture(sr, sg, sb, 0.85)
            if hi2 then
                local mr, mg, mb = Shade(r, g, b, 1.3)
                Gradient(hi2, "VERTICAL", mr, mg, mb, 0, mr, mg, mb, 0.30)
            end
        end
    end)
end

-- ============================================================================
-- Fixed-height horizontal plank wall in the colour of `role` (planks never stretch; extra height
-- is clipped). When the theme gives the role a material, one continuous layer of it replaces
-- the planks.
-- ============================================================================
function Wood.PlankWall(parent, numPlanks, role, seed)
    if parent.SetClipsChildren then parent:SetClipsChildren(true) end
    local plankH = addon.C.PLANK_H
    local rand = NewRNG(seed)

    local planks = CreateFrame("Frame", nil, parent)
    planks:SetAllPoints()
    planks:SetFrameLevel(parent:GetFrameLevel())

    local surface = parent:CreateTexture(nil, "BACKGROUND", nil, 0)
    surface:SetAllPoints()
    local wallSkin = Skin(surface, role, seed)
    parent:HookScript("OnSizeChanged", function(self, w, h) wallSkin.Map(w, h) end)
    wallSkin.Map(parent:GetWidth(), parent:GetHeight())
    Wood.Tint(role, 1, function()
        local stone = wallSkin.mat ~= nil
        surface:SetShown(stone)
        planks:SetShown(not stone)
    end)

    for i = 1, numPlanks do
        local plank = CreateFrame("Frame", nil, planks)
        plank:SetHeight(plankH)
        plank:SetPoint("TOPLEFT", parent, "TOPLEFT", 0, -((i - 1) * plankH))
        plank:SetPoint("TOPRIGHT", parent, "TOPRIGHT", 0, -((i - 1) * plankH))
        plank:SetFrameLevel(parent:GetFrameLevel() + 1)

        -- Each board gets its own tone and a hint of hue drift, like boards cut from different logs.
        local m = rand(0.84, 1.10)
        local tone = { m, m * rand(0.95, 1.04), m * rand(0.90, 1.08) }
        Wood.Paint(plank, role, seed * 31 + i, { tone = tone, light = 1.10, dark = 0.74, woodOnly = true })

        -- Groove between boards.
        local groove = Wood.Solid(plank, "OVERLAY", 1, 0.04, 0.02, 0.01, 0.95)
        groove:SetPoint("BOTTOMLEFT"); groove:SetPoint("BOTTOMRIGHT"); groove:SetHeight(2)
        local grooveShadow = plank:CreateTexture(nil, "OVERLAY", nil, 0)
        grooveShadow:SetPoint("BOTTOMLEFT", groove, "TOPLEFT"); grooveShadow:SetPoint("BOTTOMRIGHT", groove, "TOPRIGHT")
        grooveShadow:SetHeight(5)
        Gradient(grooveShadow, "VERTICAL", 0, 0, 0, 0.35, 0, 0, 0, 0)

        -- Staggered butt joints, each with two nail heads.
        local lips = {}
        local x = rand(40, 260)
        while x < 1450 do
            local seam = Wood.Solid(plank, "OVERLAY", 2, 0.05, 0.02, 0.01, 0.92)
            seam:SetWidth(2)
            seam:SetPoint("TOPLEFT", plank, "TOPLEFT", x, 0)
            seam:SetPoint("BOTTOMLEFT", plank, "BOTTOMLEFT", x, 2)
            local lip = plank:CreateTexture(nil, "OVERLAY", nil, 2)
            lip:SetAlpha(0.45)
            lip:SetWidth(1)
            lip:SetPoint("TOPLEFT", seam, "TOPRIGHT"); lip:SetPoint("BOTTOMLEFT", seam, "BOTTOMRIGHT")
            lips[#lips + 1] = lip
            local endShade = plank:CreateTexture(nil, "OVERLAY", nil, 1)
            endShade:SetWidth(8)
            endShade:SetPoint("TOPRIGHT", seam, "TOPLEFT"); endShade:SetPoint("BOTTOMRIGHT", seam, "BOTTOMLEFT")
            Gradient(endShade, "HORIZONTAL", 0, 0, 0, 0, 0, 0, 0, 0.28)

            for _, ny in ipairs({ -8, -(plankH - 10) }) do
                local nail = Wood.Disc(plank, "OVERLAY", 3, 0.10, 0.08, 0.07, 0.95)
                nail:SetSize(4, 4)
                nail:SetPoint("CENTER", seam, "TOP", 7, ny)
                local glint = Wood.Disc(plank, "OVERLAY", 4, 0.75, 0.68, 0.55, 0.65)
                glint:SetSize(1.5, 1.5)
                glint:SetPoint("CENTER", nail, "CENTER", -0.8, 0.8)
            end
            x = x + rand(260, 560)
        end
        Wood.Tint(role, tone, function(r, g, b)
            local lr, lg, lb = Shade(r, g, b, 1.7)
            for _, lip in ipairs(lips) do lip:SetColorTexture(lr, lg, lb, 1) end
        end)
    end
end

-- ============================================================================
-- Brass helpers (nameplates, tacks, bezels, buttons)
-- ============================================================================
function Wood.Brass(tex, bright, file)
    local m = bright or 1
    Wood.GradientFile(tex, file or WHITE, "VERTICAL",
        Clamp(0.45 * m), Clamp(0.32 * m), Clamp(0.12 * m), 1, Clamp(0.98 * m), Clamp(0.82 * m), Clamp(0.45 * m), 1)
end

function Wood.Nameplate(parent, width, height, fontObject)
    local plate = CreateFrame("Frame", nil, parent)
    plate:SetSize(width, height)
    local back = plate:CreateTexture(nil, "ARTWORK", nil, 0)
    back:SetPoint("TOPLEFT", -1, 1); back:SetPoint("BOTTOMRIGHT", 1, -2)
    back:SetColorTexture(0, 0, 0, 0.55)
    local face = plate:CreateTexture(nil, "ARTWORK", nil, 1)
    face:SetAllPoints()
    Wood.Brass(face)
    local rim = Wood.Solid(plate, "ARTWORK", 2, 1, 0.95, 0.75, 0.55)
    rim:SetPoint("TOPLEFT"); rim:SetPoint("TOPRIGHT"); rim:SetHeight(1)
    for _, side in ipairs({ "LEFT", "RIGHT" }) do
        local screw = Wood.Disc(plate, "ARTWORK", 3, 0.30, 0.20, 0.08, 1)
        screw:SetSize(4, 4)
        screw:SetPoint("CENTER", plate, side, side == "LEFT" and 5 or -5, 0)
    end
    local text = plate:CreateFontString(nil, "OVERLAY", fontObject or "GameFontNormalSmall")
    text:SetPoint("LEFT", 11, 0); text:SetPoint("RIGHT", -11, 0)
    text:SetJustifyH("CENTER")
    text:SetWordWrap(false)
    text:SetTextColor(0.16, 0.09, 0.02, 1)
    text:SetShadowColor(1, 0.92, 0.65, 0.6)
    text:SetShadowOffset(1, -1)
    plate.text = text
    return plate
end

-- ============================================================================
-- Cast brass (the mirror stand). Each surface is shaded across its cross-section, one 1-px
-- stripe at a time, from a surface profile lit from the upper left, so rods read as round and
-- mouldings as carved rather than as flat gradients.
-- ============================================================================
local LIGHT = { -0.45, 0.60, 0.66 } -- x (left -), y (up +), z (toward the viewer)
local BRASS_RAMP = { -- brightness -> colour
    { 0.00, 0.14, 0.08, 0.02 }, { 0.35, 0.46, 0.30, 0.09 }, { 0.60, 0.78, 0.58, 0.24 },
    { 0.85, 1.00, 0.85, 0.48 }, { 1.00, 1.00, 0.96, 0.80 },
}
local function BrassColor(v)
    v = Clamp(v)
    for i = 2, #BRASS_RAMP do
        local a, b = BRASS_RAMP[i - 1], BRASS_RAMP[i]
        if v <= b[1] then
            local t = (v - a[1]) / (b[1] - a[1])
            return a[2] + (b[2] - a[2]) * t, a[3] + (b[3] - a[3]) * t, a[4] + (b[4] - a[4]) * t
        end
    end
    local l = BRASS_RAMP[#BRASS_RAMP]
    return l[2], l[3], l[4]
end

-- Brightness of a surface with normal (nx, ny, nz): ambient + diffuse + a tight highlight.
local function Shine(nx, ny, nz)
    local len = math.sqrt(nx * nx + ny * ny + nz * nz)
    local d = math.max(0, (nx * LIGHT[1] + ny * LIGHT[2] + nz * LIGHT[3]) / len)
    return 0.14 + 0.66 * d + 0.55 * d ^ 18
end

-- Stripes across `frame`. axis "X": columns (u runs left to right); "Y": rows (u runs top to
-- bottom). shade(u) gives the brightness; along = { startMul, endMul } fakes the room reflected
-- along the length.
local function Stripes(frame, axis, count, shade, along, layer, sub)
    local list = {}
    for i = 1, count do
        local t = frame:CreateTexture(nil, layer or "BACKGROUND", nil, sub or 0)
        local v = shade((i - 0.5) / count)
        local m1, m2 = along and along[1] or 1, along and along[2] or 1
        local r1, g1, b1 = BrassColor(v * m1)
        local r2, g2, b2 = BrassColor(v * m2)
        if axis == "X" then
            Gradient(t, "VERTICAL", r2, g2, b2, 1, r1, g1, b1, 1)   -- brighter at the top
        else
            Gradient(t, "HORIZONTAL", r1, g1, b1, 1, r2, g2, b2, 1) -- brighter at the left
        end
        list[i] = t
    end
    local function Layout()
        local w, h = frame:GetWidth() or 0, frame:GetHeight() or 0
        for i, t in ipairs(list) do
            t:ClearAllPoints()
            if axis == "X" then
                t:SetPoint("TOPLEFT", frame, "TOPLEFT", (i - 1) * w / count, 0)
                t:SetPoint("BOTTOMRIGHT", frame, "BOTTOMLEFT", i * w / count, 0)
            else
                t:SetPoint("TOPLEFT", frame, "TOPLEFT", 0, -(i - 1) * h / count)
                t:SetPoint("BOTTOMRIGHT", frame, "TOPRIGHT", 0, -i * h / count)
            end
        end
    end
    frame:HookScript("OnSizeChanged", Layout)
    Layout()
    return list
end

-- A round brass rod. axis "V" = upright (posts), "H" = lying (rails, crowns).
function Wood.BrassRod(frame, axis, count)
    if axis == "V" then
        return Stripes(frame, "X", count or 10, function(u)
            local n = 2 * u - 1
            return Shine(n, 0, math.sqrt(math.max(0, 1 - n * n))) + (u > 0.82 and 0.10 or 0) -- rim light
        end, { 1.08, 0.82 })
    end
    return Stripes(frame, "Y", count or 10, function(u)
        local n = 1 - 2 * u
        return Shine(0, n, math.sqrt(math.max(0, 1 - n * n))) + (u > 0.82 and 0.08 or 0)
    end, { 1.08, 0.85 })
end

-- Picture-frame moulding cross-section, from the outer edge (u = 0) to the inner edge (u = 1).
-- Returns how much the surface faces outward (+) or inward (-), how much it faces the viewer,
-- and an occlusion factor.
local function MouldingNormal(u)
    if u < 0.30 then
        local n = 1 - 2 * (u / 0.30) -- rounded outer bead
        return n, math.sqrt(math.max(0, 1 - n * n)), 1
    elseif u < 0.42 then
        return 0.55, 0.65, 0.70     -- cove: a shadowed groove
    elseif u < 0.84 then
        return 0.05, 1, 1           -- flat face
    end
    return -0.75, 0.66, 0.9         -- inner bevel falling toward the glass
end

-- A moulded brass border `width` px wide around `frame`, optionally with a brushed plate inside.
function Wood.BrassMoulding(frame, width, fillCentre)
    for _, s in ipairs({ { "TOP", 0, 1 }, { "BOTTOM", 0, -1 }, { "LEFT", -1, 0 }, { "RIGHT", 1, 0 } }) do
        local side, dx, dy = s[1], s[2], s[3]
        local horizontal = side == "TOP" or side == "BOTTOM"
        local bar = CreateFrame("Frame", nil, frame)
        bar:SetFrameLevel(frame:GetFrameLevel())
        if horizontal then
            bar:SetPoint(side .. "LEFT"); bar:SetPoint(side .. "RIGHT"); bar:SetHeight(width)
        else
            bar:SetPoint("TOP" .. side, frame, "TOP" .. side, 0, -width)
            bar:SetPoint("BOTTOM" .. side, frame, "BOTTOM" .. side, 0, width)
            bar:SetWidth(width)
        end
        -- u runs outer to inner; on the bottom and right sides that's the reverse of stripe order.
        local reverse = side == "BOTTOM" or side == "RIGHT"
        Stripes(bar, horizontal and "Y" or "X", width, function(t)
            local out, face, occlusion = MouldingNormal(reverse and (1 - t) or t)
            return Shine(out * dx, out * dy, face) * occlusion
        end, horizontal and { 1.10, 0.86 } or { 1.08, 0.84 })
    end
    if fillCentre then
        local centre = frame:CreateTexture(nil, "BACKGROUND", nil, -1)
        centre:SetPoint("TOPLEFT", width, -width)
        centre:SetPoint("BOTTOMRIGHT", -width, width)
        local r1, g1, b1 = BrassColor(0.50)
        local r2, g2, b2 = BrassColor(0.68)
        Gradient(centre, "VERTICAL", r1, g1, b1, 1, r2, g2, b2, 1)
        -- brushed finish: the plank grain, desaturated, as faint streaks
        local brush = frame:CreateTexture(nil, "BACKGROUND", nil, 0)
        brush:SetAllPoints(centre)
        brush:SetTexture(PLANK, "REPEAT", "REPEAT")
        brush:SetDesaturated(true)
        brush:SetBlendMode("ADD")
        brush:SetVertexColor(1, 0.85, 0.55, 0.10)
    end
end

-- A cast rosette (corner boss): dark rim, domed centre, specular glint. Returns the rim texture
-- (anchor it where the rosette should sit).
function Wood.BrassRosette(parent, size, layer, sub)
    layer, sub = layer or "ARTWORK", sub or 4
    local rim = parent:CreateTexture(nil, layer, nil, sub)
    rim:SetSize(size, size)
    local rr, rg, rb = BrassColor(0.30)
    local lr, lg, lb = BrassColor(0.80)
    Wood.GradientFile(rim, DISC, "VERTICAL", rr, rg, rb, 1, lr, lg, lb, 1)
    local dome = parent:CreateTexture(nil, layer, nil, sub + 1)
    dome:SetSize(size * 0.66, size * 0.66)
    dome:SetPoint("CENTER", rim, "CENTER")
    local er, eg, eb = BrassColor(0.40)
    local dr, dg, db = BrassColor(0.95)
    Wood.GradientFile(dome, DISC, "VERTICAL", er, eg, eb, 1, dr, dg, db, 1)
    local glint = parent:CreateTexture(nil, layer, nil, sub + 2)
    glint:SetSize(math.max(2, size * 0.22), math.max(2, size * 0.22))
    glint:SetPoint("CENTER", rim, "CENTER", -size * 0.14, size * 0.14)
    glint:SetTexture(DISC)
    glint:SetVertexColor(1, 0.98, 0.9, 0.9)
    glint:SetBlendMode("ADD")
    return rim
end

-- Shorthand used by the mirror: a rod ({ cylinder = "V" | "H" }) or a moulded plate
-- ({ moulding = width in px, fill = false to leave the centre empty }).
function Wood.BrassPaint(frame, opts)
    opts = opts or {}
    if opts.cylinder then return Wood.BrassRod(frame, opts.cylinder) end
    return Wood.BrassMoulding(frame, opts.moulding or 4, opts.fill ~= false)
end

-- Round brass-rimmed button showing a game icon (Interface\Icons\<icon>), with a tooltip
-- title + description and a glow for the selected state (b:SetSelected(bool)).
function Wood.IconButton(parent, size, icon, title, desc)
    local b = CreateFrame("Button", nil, parent)
    b:SetSize(size, size)
    local shadow = Wood.Disc(b, "BACKGROUND", 0, 0, 0, 0, 0.6)
    shadow:SetPoint("TOPLEFT", 0, -2); shadow:SetPoint("BOTTOMRIGHT", 2, -2)
    local glow = Wood.Disc(b, "BACKGROUND", 1, 1, 0.85, 0.35, 0.95)
    glow:SetPoint("TOPLEFT", -4, 4); glow:SetPoint("BOTTOMRIGHT", 4, -4)
    glow:SetBlendMode("ADD")
    glow:Hide()
    local rim = b:CreateTexture(nil, "ARTWORK", nil, 0)
    rim:SetAllPoints()
    Wood.GradientFile(rim, DISC, "VERTICAL", 0.40, 0.27, 0.09, 1, 1, 0.86, 0.48, 1)
    local art = b:CreateTexture(nil, "ARTWORK", nil, 1)
    art:SetPoint("TOPLEFT", 1.5, -1.5); art:SetPoint("BOTTOMRIGHT", -1.5, 1.5)
    art:SetTexture("Interface\\Icons\\" .. icon)
    art:SetTexCoord(0.08, 0.92, 0.08, 0.92)
    b.art = art
    local mask = b:CreateMaskTexture()
    mask:SetAllPoints(art)
    mask:SetTexture(DISC, "CLAMPTOBLACKADDITIVE", "CLAMPTOBLACKADDITIVE")
    art:AddMaskTexture(mask)
    local hl = b:CreateTexture(nil, "HIGHLIGHT")
    hl:SetAllPoints()
    hl:SetTexture(DISC)
    hl:SetVertexColor(1, 0.95, 0.7, 0.35)
    hl:SetBlendMode("ADD")
    b:HookScript("OnMouseDown", function() art:SetPoint("TOPLEFT", 2, -2) end)
    b:HookScript("OnMouseUp", function() art:SetPoint("TOPLEFT", 1.5, -1.5) end)
    b:HookScript("OnEnter", function(self)
        GameTooltip:SetOwner(self, "ANCHOR_TOP")
        GameTooltip:SetText(title, 1, 1, 1)
        if desc then GameTooltip:AddLine(desc, 1, 0.82, 0, true) end
        GameTooltip:Show()
    end)
    b:HookScript("OnLeave", function() GameTooltip:Hide() end)
    function b:SetSelected(on) glow:SetShown(on and true or false) end
    return b
end

-- Round brass stud button with a short glyph/label. Used by the plinth and pager.
function Wood.BrassButton(parent, size, label, tooltip)
    local b = CreateFrame("Button", nil, parent)
    b:SetSize(size, size)
    local shadow = Wood.Disc(b, "BACKGROUND", 0, 0, 0, 0, 0.6)
    shadow:SetPoint("TOPLEFT", 0, -2); shadow:SetPoint("BOTTOMRIGHT", 2, -2)
    local rim = b:CreateTexture(nil, "ARTWORK", nil, 0)
    rim:SetAllPoints()
    Wood.GradientFile(rim, DISC, "VERTICAL", 0.95, 0.78, 0.40, 1, 0.30, 0.20, 0.07, 1)
    local face = b:CreateTexture(nil, "ARTWORK", nil, 1)
    face:SetPoint("TOPLEFT", 1.5, -1.5); face:SetPoint("BOTTOMRIGHT", -1.5, 1.5)
    Wood.Brass(face, 1, DISC)
    b.face = face
    local hl = b:CreateTexture(nil, "HIGHLIGHT")
    hl:SetAllPoints()
    hl:SetTexture(DISC)
    hl:SetVertexColor(1, 0.95, 0.7, 0.35)
    hl:SetBlendMode("ADD")
    local text = b:CreateFontString(nil, "OVERLAY", "GameFontNormalSmall")
    text:SetPoint("CENTER", 0, 0.5)
    text:SetText(label)
    text:SetTextColor(0.22, 0.12, 0.03, 1)
    text:SetShadowColor(1, 0.95, 0.75, 0.6)
    text:SetShadowOffset(0.5, -0.5)
    b.text = text
    b:HookScript("OnMouseDown", function() text:SetPoint("CENTER", 0.5, -0.5) end)
    b:HookScript("OnMouseUp", function() text:SetPoint("CENTER", 0, 0.5) end)
    if tooltip then
        b:HookScript("OnEnter", function(self)
            GameTooltip:SetOwner(self, "ANCHOR_TOP")
            GameTooltip:SetText(type(tooltip) == "function" and tooltip(self) or tooltip, 1, 1, 1)
            GameTooltip:Show()
        end)
        b:HookScript("OnLeave", function() GameTooltip:Hide() end)
    end
    return b
end
